        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1].results || {};
            var trust = last.trust || 0;
            var resilience = last.resilience || 0;
            var adaptive = last.adaptiveCapacity || 0;
            var cultural = last.culturalIntegrity || 0;
            var financial = (last.financialHealth || 0) * 10;

            var optimalPeriods = 0;
            history.forEach(function(h) {
                var temp = h.results ? h.results.temperature : 50;
                if (temp >= 45 && temp <= 65) optimalPeriods++;
            });
            var tempScore = history.length > 0 ? (optimalPeriods / history.length) * 100 : 0;

            var cli = trust * 0.25 + resilience * 0.25 + adaptive * 0.20 + cultural * 0.15 + financial * 0.10 + tempScore * 0.05;

            var performance = 'Developing Leader';
            if (cli >= 80) performance = 'Exceptional Crisis Leader';
            else if (cli >= 65) performance = 'Effective Crisis Leader';
            else if (cli >= 50) performance = 'Competent Manager';

            var insights = [];
            if (trust >= 75) insights.push('Strong stakeholder trust — effective crisis communication.');
            if (trust < 50) insights.push('Trust eroded significantly — review communication decisions.');
            if (adaptive >= 70) insights.push('High adaptive capacity — leadership was well distributed.');
            if (adaptive < 40) insights.push('Low adaptive capacity — consider delegating more in future crises.');
            if (cultural >= 70) insights.push('Cultural integrity maintained through the transformation.');
            if (cultural < 40) insights.push('Cultural integrity suffered — values and actions became misaligned.');
            if (financial < 4) insights.push('Financial health is critical — review cost management decisions.');
            if (tempScore >= 70) insights.push('Organizational temperature well managed in the productive zone.');
            if (tempScore < 30) insights.push('Temperature frequently outside the productive zone (45-65).');

            return {
                cli: Math.round(cli),
                performance: performance,
                trust: Math.round(trust),
                resilience: Math.round(resilience),
                adaptiveCapacity: Math.round(adaptive),
                culturalIntegrity: Math.round(cultural),
                financialHealth: last.financialHealth ? last.financialHealth.toFixed(1) : '0',
                temperatureOptimal: Math.round(tempScore),
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (state.domainState.temperature > 75) return window.mySimulation.t('hint_high_temp');
            if (state.domainState.temperature < 35) return window.mySimulation.t('hint_low_temp');
            if (state.domainState.trust < 35) return window.mySimulation.t('hint_low_trust');
            if (state.domainState.financialHealth < 2.5) return window.mySimulation.t('hint_financial_danger');
            if (state.domainState.adaptiveCapacity < 30) return window.mySimulation.t('hint_low_adaptive');
            return null;
        }

